    >
      <style>{"/* Estilos demo */\n    body { font-family: 'Segoe UI', sans-serif; margin: 0; background: #111; color: white; overflow-x: hidden; }\n    h1 { text-align: center; margin-top: 50px; font-weight: 300; }\n    \n    /* Cajas para visualizar el efecto */\n    .card {\n        background: linear-gradient(135deg, #4b6cb7 0%, #182848 100%);\n        min-height: 400px;\n        margin: 50px auto;\n        width: 80%;\n        max-width: 800px;\n        border-radius: 20px;\n        display: flex;\n        justify-content: center;\n        align-items: center;\n        font-size: 2rem;\n        box-shadow: 0 10px 30px rgba(0,0,0,0.5);\n    }"}</style>
      <h1>Scroll Down to see the Magic 👇</h1>

        <div className="card reveal">
          <span>✨ Floating Card 1</span>
        </div>

        <div className="card reveal">
          <span>🚀 Floating Card 2</span>
        </div>

        <div className="card reveal">
          <span>🎨 Floating Card 3</span>
        </div>
    </div>
  )
}

export { SmoothScaleFloatReveal }
